const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr = esc;
const text = value => typeof value === 'string' ? value : Array.isArray(value) ? value.join('\n') : value == null ? '' : JSON.stringify(value);
const lines = value => String(value || '').split(/\n/).map(x => x.trim()).filter(Boolean);
const date = value => { if (!value) return '未知'; const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value) : d.toLocaleDateString('zh-CN', {timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit'}); };
const dateTime = value => { if (!value) return '尚未运行'; const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value) : d.toLocaleString('zh-CN', {timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}); };
const option = (value, label, selected) => `<option value="${attr(value)}" ${String(value) === String(selected) ? 'selected' : ''}>${esc(label)}</option>`;
const group = job => ({meets:'confirmed',eligible:'confirmed',clear:'confirmed',definite:'confirmed',insufficient:'unknown','明确符合':'confirmed','可能符合':'possible','信息不足':'unknown','低于目标':'below'}[job.salary_group] || job.salary_group || 'unknown');
const groupLabel = key => ({confirmed:'固定月薪符合',possible:'薪资可能符合',unknown:'薪资待核实',below:'薪资低于目标'}[key] || key);
const safeUrl = value => { try { const url = new URL(value, location.origin); return ['https:','http:'].includes(url.protocol) ? url.href : '#'; } catch { return '#'; } };
const fieldLabel = key => labels[key] || key;
const checked = value => value ? 'checked' : '';
const statusTag = value => `<span class="tag ${['可投','Offer'].includes(value)?'green':value==='面试中'?'purple':value==='已关闭'?'red':''}">${esc(value || '待看')}</span>`;

// All mutating requests carry the session's CSRF token; uploads retain multipart boundaries.
async function api(path, options = {}) {
  const headers = { ...(options.headers || {}) };
  if (options.body && !(options.body instanceof FormData)) { headers['Content-Type'] = 'application/json'; options.body = JSON.stringify(options.body); }
  if (options.method && !['GET','HEAD'].includes(options.method)) headers['X-CSRF-Token'] = state.csrf;
  const response = await fetch(path, { credentials: 'same-origin', ...options, headers });
  let data;
  try { data = await response.json(); } catch { data = {detail: response.ok ? '服务未返回有效数据。' : `请求失败（${response.status}）`}; }
  if (!response.ok) {
    if (response.status === 401) showLogin();
    const detail = Array.isArray(data.detail) ? data.detail.map(x=>x.msg || JSON.stringify(x)).join('；') : data.detail;
    throw new Error(detail || data.error || `请求失败（${response.status}）`);
  }
  return data;
}
function toast(message, error = false) { const el = document.createElement('div'); el.className = `toast${error?' error':''}`; el.setAttribute('role','status'); el.textContent = message; $('#toast-stack').append(el); setTimeout(()=>el.remove(), error?8500:4300); }
async function busy(button, action, label = '正在处理…') { const old = button?.innerHTML; if(button){button.disabled=true;button.innerHTML=`<span class="busy-inline"></span>${esc(label)}`;} try {return await action();} catch(error){toast(error.message,true);return null;} finally{if(button?.isConnected){button.disabled=false;button.innerHTML=old;}} }
function showLogin(){ $('#login-screen').hidden=false; $('#app').hidden=true; clearInterval(state.poll); }
function empty(title, description, action = '', compact = false) { return `<div class="empty-state ${compact?'compact':''}"><div class="empty-symbol">⌁</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`; }
function pageHead(eyebrow, title, subtitle, actions=''){return `<div class="page-head"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1><p class="page-subtitle">${esc(subtitle)}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;}
function notice(message, type=''){return `<div class="notice ${type}">${esc(message)}</div>`;}

// Recursively render structured backend output while escaping every string (including AI output).
function renderData(value, depth = 0) {
  if (value === null || value === undefined || value === '') return '<span class="muted">待补充</span>';
  if (typeof value === 'boolean') return value ? '是' : '否';
  if (typeof value !== 'object') return `<span class="data-value">${esc(value)}</span>`;
  if (Array.isArray(value)) {
    if (!value.length) return '<span class="muted">暂无记录</span>';
    if (value.every(v => typeof v !== 'object' || v === null)) return `<ul class="data-list">${value.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;
    return value.map(v=>`<div class="data-object">${renderData(v, depth+1)}</div>`).join('');
  }
  return Object.entries(value).filter(([key])=>!['id','job_id','resume_id','created_at','updated_at'].includes(key)).map(([key,val])=>{
    const complex=val && typeof val==='object';
    if(complex && depth===0) return `<section class="data-section"><h3>${esc(fieldLabel(key))}</h3>${renderData(val,depth+1)}</section>`;
    return `<div class="data-field"><span class="data-key">${esc(fieldLabel(key))}</span><div class="data-value">${complex?renderData(val,depth+1):esc(typeof val==='boolean'?(val?'是':'否'):val??'未知')}</div></div>`;
  }).join('');
}

function jobCard(job, index=0) {
  const category=group(job), skills=Array.isArray(job.requirements)?job.requirements: String(job.requirements||'').split(/[、,，;；\n]/).filter(x=>x.trim().length<28).slice(0,3);
  const reason=job.recommendation_reason || job.match_reason || job.reason || (state.profile?.preferred_city&&String(job.city||'').includes(state.profile.preferred_city)?`地点符合${state.profile.preferred_city}优先偏好`:job.city?`${job.city} · 可单独评估城市意愿`:'工作地点待核实');
  return `<article class="job-card"><div class="company-icon tone-${index%4}">${esc((job.company||'?').slice(0,1))}</div><div class="job-main"><div class="job-title-row"><a class="job-title" href="#job/${job.id}">${esc(job.title||'待核对岗位名称')}</a><span class="salary">${esc(job.salary_raw||'薪资未知')}</span></div><div class="job-company">${esc(job.company||'公司未知')} ${job.is_sample?'<span class="tag amber">样例</span>':''}</div><div class="job-meta"><span>${esc(job.city||'城市待确认')}</span><span>${esc(job.experience||'经验未注明')}</span><span>${esc(job.education||'学历未注明')}</span></div><div class="job-tags"><span class="tag ${category==='confirmed'?'green':category==='possible'?'amber':''}">${esc(groupLabel(category))}</span>${job.constraint_fit?`<span class="tag ${job.constraint_fit.code==='meets'?'green':'amber'}">${esc(job.constraint_fit.label)}</span>`:''}${skills.slice(0,3).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}${job.analysis?.evidence_coverage?`<span class="tag">实践证据 ${job.analysis.evidence_coverage.confirmed}/${job.analysis.evidence_coverage.total} 项</span>`:''}${statusTag(job.status)}</div><p class="job-reason">${esc(reason)}</p><div class="job-footer"><span class="job-date">发现 ${date(job.first_seen)} · ${job.published_at?`发布 ${date(job.published_at)}`:'发布时间未知'}</span><div class="inline-actions"><button class="star-button ${job.favorite?'active':''}" data-action="favorite" data-id="${job.id}" data-value="${!job.favorite}" aria-label="${job.favorite?'取消收藏':'收藏岗位'}">${job.favorite?'★':'☆'}</button><a class="button small" href="#job/${job.id}">查看岗位 <span>↗</span></a></div></div></div></article>`;
}
function sourcesPanel(sources){return `<section class="panel"><div class="panel-head"><h3>数据来源</h3><a href="#settings" class="help">管理 ↗</a></div>${(sources||[]).map((source,i)=>`<div class="source-row"><span class="source-logo">${esc((source.name||'源').slice(0,2))}</span><div class="source-info"><strong>${esc(source.name)}</strong><small title="${attr(source.message||source.reason||source.url||'')}">${esc(source.message||source.reason||source.kind||'待配置')}</small></div><span class="source-status ${['connected','已连接'].includes(source.status)?'connected':''}">${esc(sourceStatus(source.status))}</span></div>`).join('') || '<p class="help">暂无数据源。可在设置中添加公开招聘源。</p>'}<p class="side-note">仅获取公开或已授权的数据。平台不可访问时，不会据此判定岗位已关闭。</p></section>`;}
function sourceStatus(value){return {connected:'已连接',needs_config:'需要配置',unsupported:'暂不支持',failed:'最近获取失败',disabled:'未启用',available:'可连接',not_verified:'待核验'}[value]||value||'需要配置';}

