  const list=state.salary==='all'?jobs:jobs.filter(j=>group(j)===state.salary);
  const preferredCity=data.profile?.preferred_city||'深圳';const inPreferredCity=job=>Boolean(preferredCity&&String(job.city||'').includes(preferredCity));const priority=list.filter(inPreferredCity), other=list.filter(j=>!inPreferredCity(j));
